const a="http://127.0.0.1:3000/api";async function c(){try{const e=await fetch(`${a}/health`,{method:"GET",headers:{Accept:"application/json"}});return e.ok?await e.json():{status:"error",error:`Server responded with ${e.status}`}}catch{return{status:"error",error:"Capture Server is unreachable. Make sure backend is running on port 3000."}}}async function i(){try{const e=await fetch(`${a}/tools`,{method:"GET",headers:{Accept:"application/json"}});if(!e.ok)throw new Error(`Server returned HTTP ${e.status}`);return await e.json()}catch(e){throw console.warn("[API Client] Error fetching tools from backend:",e.message),e}}async function u(e,r="extension",t,o){try{const s=await fetch(`${a}/tools`,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({url:e,source:r,sourceUrl:t,tool:o})}),n=await s.json();return s.ok?n:{success:!1,error:n.error||`Server error (HTTP ${s.status})`}}catch{return{success:!1,error:"Unable to connect to Capture Server."}}}async function h(e){try{const r=await fetch(`${a}/analyze-url`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({url:e})}),t=await r.json();return r.ok?t:{success:!1,error:t.error||"Failed to analyze URL"}}catch{return{success:!1,error:"Network error. Capture server may be unreachable."}}}async function y(e,r){try{const t=await fetch(`${a}/analyze-video`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({url:e,additionalText:r})}),o=await t.json();return t.ok?o:{success:!1,error:o.error||"Failed to analyze video URL"}}catch{return{success:!1,error:"Network error. Capture server may be unreachable."}}}async function l(e,r){try{return await(await fetch(`${a}/tools/${e}`,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(r)})).json()}catch{return{success:!1,error:"Network error."}}}async function f(e){try{return await(await fetch(`${a}/tools/${e}`,{method:"DELETE"})).json()}catch{return{success:!1,error:"Network error."}}}async function d(){try{const e=await fetch(`${a}/categories`);return e.ok?await e.json():[]}catch{return[]}}async function p(e){return await(await fetch(`${a}/categories`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:e})})).json()}async function w(e,r){return await(await fetch(`${a}/categories/${e}`,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:r})})).json()}async function T(e){return await(await fetch(`${a}/categories/${e}`,{method:"DELETE"})).json()}export{d as a,p as b,c,T as d,w as e,i as f,f as g,l as h,h as i,y as j,u as s};
